class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        # Identify all contiguous blocks of identical characters
        # e.g., "aaabaaa" -> {'a': [3, 3], 'b': [1]}
        blocks = defaultdict(list)
        if not s:
            return -1

        n = len(s)
        i = 0
        while i < n:
            char = s[i]
            count = 0
            while i < n and s[i] == char:
                count += 1
                i += 1
            blocks[char].append(count)

        ans = -1

        # For each character, we have a list of lengths of contiguous blocks.
        # A block of length L provides:
        # 1 occurrence of length L
        # 2 occurrences of length L-1
        # (L-k+1) occurrences of length k (for k <= L)
        # We want the largest k such that total occurrences >= 3.

        for char in blocks:
            lengths = blocks[char]
            # Check possible lengths k from max possible down to 1
            for k in range(max(lengths), 0, -1):
                total_occurrences = 0
                for L in lengths:
                    if L >= k:
                        total_occurrences += (L - k + 1)

                if total_occurrences >= 3:
                    ans = max(ans, k)
                    break

        return ans
